      + eapply frame_mod_trans_same; [exact FM'|]. eapply sw_post_frame_mod; [exact HPOST|].
        intros x Hx. unfold tail_regions, OT_FR in Hx. cbn [OSSVerify.Proofs.boost_json.fuzz_parse.lib.Frame.outside] in Hx. unfold OSSVerify.Proofs.boost_json.fuzz_parse.lib.Frame.in_rng in Hx. rewrite spm_u in Hx.
        ed_lin ltac:(cbn [ev ENV]; rewrite ?P0). revert Hx. unorm. intros (N1 & N2 & _). lia.
  Qed.
